import subprocess
import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

# Configuration
ALLOWED_REPORTS = ['sales', 'inventory', 'audit', 'compliance']
REPORT_BASE_DIR = '/opt/reports/templates'

def sanitize_filename(name):
    """Remove path traversal attempts - basic sanitization"""
    # Strip leading/trailing whitespace
    name = name.strip()
    # Remove null bytes
    name = name.replace('\x00', '')
    return name

def generate_report(report_type, output_format, date_range):
    """Generate report using system wkhtmltopdf or pandoc"""
    template_path = os.path.join(REPORT_BASE_DIR, f"{report_type}.html")

    if not os.path.exists(template_path):
        return None, "Template not found"

    output_file = f"/tmp/report_{report_type}_{date_range}.{output_format}"

    # Build command based on output format
    if output_format == 'pdf':
        cmd = f"wkhtmltopdf --quiet {template_path} {output_file}"
    elif output_format == 'docx':
        cmd = f"pandoc {template_path} -o {output_file}"
    else:
        cmd = f"cat {template_path} | head -100 > {output_file}"

    # Execute report generation
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)

    if result.returncode != 0:
        return None, f"Generation failed: {result.stderr.decode()[:200]}"

    return output_file, None

@app.route('/api/reports/generate', methods=['POST'])
def api_generate_report():
    data = request.get_json()

    if not data:
        return jsonify({"error": "JSON body required"}), 400

    report_type = data.get('report_type', '')
    output_format = data.get('format', 'pdf')
    date_range = data.get('date_range', 'last_30d')

    # Validate report type
    report_type = sanitize_filename(report_type)
    if report_type not in ALLOWED_REPORTS:
        return jsonify({"error": "Invalid report type"}), 400

    # Validate date range format
    if not re.match(r'^[a-z0-9_]{1,20}$', date_range):
        return jsonify({"error": "Invalid date range"}), 400

    # Generate the report
    output_file, error = generate_report(report_type, output_format, date_range)

    if error:
        return jsonify({"error": error}), 500

    return jsonify({"status": "success", "file": output_file})

@app.route('/api/reports/custom', methods=['POST'])
def api_custom_report():
    """Advanced endpoint for custom report generation with user-specified parameters"""
    data = request.get_json()

    if not data:
        return jsonify({"error": "JSON body required"}), 400

    title = data.get('title', 'Untitled')
    query_filter = data.get('filter', '')
    output_format = data.get('format', 'pdf')

    # Build custom report command
    # The filter parameter allows specifying data selection criteria
    cmd = f"/opt/reports/gen_custom.sh '{title}' '{query_filter}' {output_format}"

    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=60)
        if result.returncode == 0:
            return jsonify({"status": "success", "output": result.stdout.decode()[:500]})
        else:
            return jsonify({"error": "Report generation failed"}), 500
    except subprocess.TimeoutExpired:
        return jsonify({"error": "Timeout"}), 504

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
